group_by(Año) %&gt;% summarise(Promedio_PM10 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) pm10_anual %&gt;% mutate(Promedio_PM10 = round(Promedio_PM10, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio PM10&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio PM10 Número de registros 2011 42.66 143 2012 44.60 162 2013 42.07 161 2014 43.64 164 2015 44.40 182 2016 43.65 177 2017 37.70 227 2018 36.99 222 2019 35.78 211 2020 35.90 267 2021 33.20 251 2022 31.88 263 2023 30.89 280 2024 30.83 275 # Evolución del promedio anual de PM10 ggplot(pm10_anual, aes(x = Año, y = Promedio_PM10)) + geom_line(linewidth = 1) + geom_point(size = 2.5) + geom_text(aes(label = round(Promedio_PM10, 1)), vjust = -0.8, size = 3.5) + scale_x_continuous(breaks = 2011:2024) + labs(title = &quot;Evolución del promedio anual de PM10&quot;, subtitle = &quot;Periodo 2011–2024&quot;, x = &quot;Año&quot;, y = &quot;Promedio de PM10&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), axis.text.x = element_text(angle = 45, hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(pm10_anual$Promedio_PM10) * 1.08) Interpretación. El PM10 se mantuvo cerca de 43–44 µg/m³ entre 2011 y 2016 y desde 2017 baja de forma sostenida hasta 30,8 µg/m³ en 2024. Es la tendencia más estable de todos los contaminantes. Como referencia, la Resolución 2254 de 2017 fija un nivel anual de 50 µg/m³ y una meta de 30 µg/m³ a 2030: el promedio nacional estuvo por debajo del nivel vigente todos los años y en 2024 quedó muy cerca de la meta futura. Es solo una referencia, porque el promedio mezcla registros de 1 y 24 horas de exposición. # Filtrar los registros de PM10 pm10 &lt;- df %&gt;% filter(Variable == &quot;PM10&quot;) # Promedio anual de PM10 pm10_anual &lt;- pm10 %&gt;% group_by(Año) %&gt;% summarise( Promedio_PM10 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot; ) %&gt;% arrange(Año) # Mostrar tabla pm10_anual %&gt;% mutate( Promedio_PM10 = round(Promedio_PM10, 2) ) %&gt;% knitr::kable( col.names = c(&quot;Año&quot;, &quot;Promedio PM10&quot;, &quot;Número de registros&quot;) ) %&gt;% kableExtra::kable_styling( full_width = FALSE, position = &quot;left&quot; ) %&gt;% kableExtra::column_spec( 1:3, border_right = TRUE ) Año Promedio PM10 Número de registros 2011 42.66 143 2012 44.60 162 2013 42.07 161 2014 43.64 164 2015 44.40 182 2016 43.65 177 2017 37.70 227 2018 36.99 222 2019 35.78 211 2020 35.90 267 2021 33.20 251 2022 31.88 263 2023 30.89 280 2024 30.83 275 # Cambio porcentual de PM10 entre 2011 y 2024 PM10_2011 &lt;- pm10_anual$Promedio_PM10[pm10_anual$Año == 2011] PM10_2024 &lt;- pm10_anual$Promedio_PM10[pm10_anual$Año == 2024] cambio_porcentual &lt;- ((PM10_2024 - PM10_2011) / PM10_2011) * 100 tabla_cambio_pm10 &lt;- data.frame( Periodo = &quot;2011-2024&quot;, Promedio_2011 = PM10_2011, Promedio_2024 = PM10_2024, Cambio_porcentual = cambio_porcentual ) tabla_cambio_pm10 %&gt;% mutate( Promedio_2011 = round(Promedio_2011, 2), Promedio_2024 = round(Promedio_2024, 2), Cambio_porcentual = round(Cambio_porcentual, 2) ) %&gt;% knitr::kable( col.names = c( &quot;Periodo&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot; ) ) %&gt;% kableExtra::kable_styling( full_width = FALSE, position = &quot;left&quot; ) %&gt;% kableExtra::column_spec( 1:4, border_right = TRUE ) Periodo Promedio 2011 Promedio 2024 Cambio (%) 2011-2024 42.66 30.83 -27.75 Interpretación. Entre 2011 y 2024 el PM10 bajó 27,75 %. 2.7.2 PM2.5 # Estadística descriptiva de PM2.5 pm25 &lt;- df %&gt;% filter(Variable == &quot;PM2.5&quot;) estadistica_pm25 &lt;- data.frame( Estadistico = c( &quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot; ), Valor = c( min(pm25$Promedio, na.rm = TRUE), quantile(pm25$Promedio, 0.25, na.rm = TRUE), median(pm25$Promedio, na.rm = TRUE), mean(pm25$Promedio, na.rm = TRUE), quantile(pm25$Promedio, 0.75, na.rm = TRUE), max(pm25$Promedio, na.rm = TRUE) ) ) estadistica_pm25 %&gt;% mutate(Valor = round(Valor, 2)) %&gt;% knitr::kable( col.names = c(&quot;Estadístico&quot;, &quot;Valor&quot;) ) %&gt;% kableExtra::kable_styling( full_width = FALSE, position = &quot;left&quot; ) %&gt;% kableExtra::column_spec( 1:2, border_right = TRUE ) Estadístico Valor Mínimo 2.70 Primer cuartil 12.50 Mediana 15.70 Media 16.84 Tercer cuartil 19.80 Máximo 68.60 Interpretación. El PM2.5 tiene menos registros que el PM10 y valores más bajos, lo esperable porque es la fracción fina del material particulado. La media (16,8 µg/m³) y la mediana (15,7 µg/m³) son cercanas. # PM2.5: promedio y número de registros por año pm25_anual &lt;- pm25 %&gt;% group_by(Año) %&gt;% summarise(Promedio_PM25 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) pm25_anual %&gt;% mutate(Promedio_PM25 = round(Promedio_PM25, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio PM2.5&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio PM2.5 Número de registros 2011 21.46 19 2012 23.88 33 2013 22.16 40 2014 21.48 55 2015 22.39 59 2016 23.68 65 2017 18.58 142 2018 16.53 162 2019 18.51 139 2020 16.98 233 2021 15.49 240 2022 15.39 258 2023 14.00 268 2024 14.73 271 # Evolución del promedio anual de PM2.5 ggplot(pm25_anual, aes(x = Año, y = Promedio_PM25)) + geom_line(linewidth = 1) + geom_point(size = 2.5) + geom_text(aes(label = round(Promedio_PM25, 1)), vjust = -0.8, size = 3.5) + scale_x_continuous(breaks = 2011:2024) + labs(title = &quot;Evolución del promedio anual de PM2.5&quot;, subtitle = &quot;Periodo 2011–2024&quot;, x = &quot;Año&quot;, y = &quot;Promedio de PM2.5&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), axis.text.x = element_text(angle = 45, hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(pm25_anual$Promedio_PM25) * 1.08) Interpretación. El PM2.5 cae con fuerza en 2017, de 23,7 a 18,6 µg/m³. Ese salto coincide con que el número de registros se duplicó (de 65 a 142): al entrar estaciones nuevas, posiblemente en zonas menos contaminadas, el promedio puede bajar sin que el aire haya mejorado en las estaciones existentes. Es un efecto de composición de la red que este EDA no puede descartar. En 2023 y 2024 el promedio nacional (14,0 y 14,7 µg/m³) está por debajo de la meta a 2030 de la Res. 2254/2017 (15 µg/m³). # Cambio porcentual de PM2.5 entre 2011 y 2024 tabla_cambio_pm25 &lt;- data.frame(Periodo = &quot;2011–2024&quot;, PM25_2011 = pm25_anual$Promedio_PM25[pm25_anual$Año == 2011], PM25_2024 = pm25_anual$Promedio_PM25[pm25_anual$Año == 2024], Cambio_porcentual = ((pm25_anual$Promedio_PM25[pm25_anual$Año == 2024] - pm25_anual$Promedio_PM25[pm25_anual$Año == 2011]) / pm25_anual$Promedio_PM25[pm25_anual$Año == 2011]) * 100) tabla_cambio_pm25 %&gt;% mutate(across(where(is.numeric), ~round(.x, 2))) %&gt;% knitr::kable(col.names = c(&quot;Periodo&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:4, border_right = TRUE) Periodo Promedio 2011 Promedio 2024 Cambio (%) 2011–2024 21.46 14.73 -31.35 Interpretación. Entre 2011 y 2024 el PM2.5 bajó 31,35 %. 2.7.3 NO₂ # Estadística descriptiva de NO2 no2 &lt;- df %&gt;% filter(Variable == &quot;NO2&quot;) estadistica_no2 &lt;- data.frame(Estadistico = c(&quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot;), Valor = c(min(no2$Promedio, na.rm = TRUE), quantile(no2$Promedio, 0.25, na.rm = TRUE), median(no2$Promedio, na.rm = TRUE), mean(no2$Promedio, na.rm = TRUE), quantile(no2$Promedio, 0.75, na.rm = TRUE), max(no2$Promedio, na.rm = TRUE))) estadistica_no2 %&gt;% mutate(Valor = round(Valor, 2)) %&gt;% knitr::kable(col.names = c(&quot;Estadístico&quot;, &quot;Valor&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:2, border_right = TRUE) Estadístico Valor Mínimo 0.50 Primer cuartil 16.50 Mediana 26.00 Media 26.46 Tercer cuartil 35.60 Máximo 65.60 Interpretación. El NO₂ tiene solo 644 registros, entre 20 y 59 por año. La media y la mediana son prácticamente iguales (26,5 y 26,0 µg/m³), una distribución bastante simétrica. # NO2: promedio y número de registros por año no2_anual &lt;- no2 %&gt;% group_by(Año) %&gt;% summarise(Promedio_NO2 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) no2_anual %&gt;% mutate(Promedio_NO2 = round(Promedio_NO2, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio NO2&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio NO2 Número de registros 2011 36.28 40 2012 31.77 48 2013 30.52 43 2014 24.85 49 2015 24.36 53 2016 28.28 48 2017 21.32 59 2018 24.27 30 2019 23.32 20 2020 24.39 49 2021 24.31 57 2022 26.13 50 2023 25.05 48 2024 26.88 50 # Evolución del promedio anual de NO2 ggplot(no2_anual, aes(x = Año, y = Promedio_NO2)) + geom_line(linewidth = 1) + geom_point(size = 2.5) + geom_text(aes(label = round(Promedio_NO2, 1)), vjust = -0.8, size = 3.5) + scale_x_continuous(breaks = 2011:2024) + labs(title = &quot;Evolución del promedio anual de NO2&quot;, subtitle = &quot;Periodo 2011–2024&quot;, x = &quot;Año&quot;, y = &quot;Promedio de NO2&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), axis.text.x = element_text(angle = 45, hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(no2_anual$Promedio_NO2) * 1.08) Interpretación. El NO₂ bajó con fuerza entre 2011 y 2017 (de 36,3 a 21,3 µg/m³), pero desde entonces sube lentamente hasta 26,9 µg/m³ en 2024. El cambio total esconde ese repunte. El NO₂ proviene sobre todo de la combustión vehicular, así que el repunte podría reflejar el aumento del parque automotor. Todos los valores están muy por debajo del nivel anual vigente (60 µg/m³) y de la meta 2030 (40 µg/m³). tabla_cambio_no2 &lt;- data.frame(Periodo = &quot;2011–2024&quot;, NO2_2011 = no2_anual$Promedio_NO2[no2_anual$Año == 2011], NO2_2024 = no2_anual$Promedio_NO2[no2_anual$Año == 2024], Cambio_porcentual = ((no2_anual$Promedio_NO2[no2_anual$Año == 2024] - no2_anual$Promedio_NO2[no2_anual$Año == 2011]) / no2_anual$Promedio_NO2[no2_anual$Año == 2011]) * 100) tabla_cambio_no2 %&gt;% mutate(across(where(is.numeric), ~round(.x, 2))) %&gt;% knitr::kable(col.names = c(&quot;Periodo&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:4, border_right = TRUE) Periodo Promedio 2011 Promedio 2024 Cambio (%) 2011–2024 36.28 26.88 -25.9 Interpretación. Entre 2011 y 2024 el NO₂ bajó 25,90 %, pero con el repunte desde 2017 descrito arriba. 2.7.4 O₃ # Estadística descriptiva de O3 o3 &lt;- df %&gt;% filter(Variable == &quot;O3&quot;) estadistica_o3 &lt;- data.frame(Estadistico = c(&quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot;), Valor = c(min(o3$Promedio, na.rm = TRUE), quantile(o3$Promedio, 0.25, na.rm = TRUE), median(o3$Promedio, na.rm = TRUE), mean(o3$Promedio, na.rm = TRUE), quantile(o3$Promedio, 0.75, na.rm = TRUE), max(o3$Promedio, na.rm = TRUE))) estadistica_o3 %&gt;% mutate(Valor = round(Valor, 2)) %&gt;% knitr::kable(col.names = c(&quot;Estadístico&quot;, &quot;Valor&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:2, border_right = TRUE) Estadístico Valor Mínimo 2.00 Primer cuartil 19.80 Mediana 25.70 Media 26.15 Tercer cuartil 31.80 Máximo 65.80 # O3: promedio y número de registros por año o3_anual &lt;- o3 %&gt;% group_by(Año) %&gt;% summarise(Promedio_O3 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) o3_anual %&gt;% mutate(Promedio_O3 = round(Promedio_O3, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio O3&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio O3 Número de registros 2011 23.94 40 2012 27.55 58 2013 27.86 54 2014 29.01 58 2015 32.64 66 2016 26.74 70 2017 24.23 107 2018 23.94 48 2019 25.00 35 2020 25.92 55 2021 22.68 57 2022 24.93 65 2023 23.53 55 2024 27.29 59 # Evolución del promedio anual de O3 ggplot(o3_anual, aes(x = Año, y = Promedio_O3)) + geom_line(linewidth = 1) + geom_point(size = 2.5) + geom_text(aes(label = round(Promedio_O3, 1)), vjust = -0.8, size = 3.5) + scale_x_continuous(breaks = 2011:2024) + labs(title = &quot;Evolución del promedio anual de O3&quot;, subtitle = &quot;Periodo 2011–2024&quot;, x = &quot;Año&quot;, y = &quot;Promedio de O3&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), axis.text.x = element_text(angle = 45, hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(o3_anual$Promedio_O3) * 1.08) Interpretación. El ozono no muestra una tendencia clara: sube hasta 32,6 µg/m³ en 2015, baja hasta 22,7 µg/m³ en 2021 y vuelve a subir en 2024. El O₃ no se emite directamente: se forma en la atmósfera a partir de óxidos de nitrógeno y compuestos orgánicos con la radiación solar. Por eso puede subir aunque bajen otros contaminantes. # Cambio porcentual de O3 entre 2011 y 2024 cambio_o3 &lt;- ((o3_anual$Promedio_O3[o3_anual$Año == 2024] - o3_anual$Promedio_O3[o3_anual$Año == 2011]) / o3_anual$Promedio_O3[o3_anual$Año == 2011]) * 100 # Tabla de cambio porcentual de O3 tabla_cambio_o3 &lt;- data.frame(Periodo = &quot;2011–2024&quot;, O3_2011 = o3_anual$Promedio_O3[o3_anual$Año == 2011], O3_2024 = o3_anual$Promedio_O3[o3_anual$Año == 2024], Cambio_porcentual = cambio_o3) tabla_cambio_o3 %&gt;% mutate(across(where(is.numeric), ~round(.x, 2))) %&gt;% knitr::kable(col.names = c(&quot;Periodo&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:4, border_right = TRUE) Periodo Promedio 2011 Promedio 2024 Cambio (%) 2011–2024 23.94 27.29 14 Interpretación. El ozono es el único contaminante que aumentó entre 2011 y 2024 (+14,0 %). 2.7.5 SO₂ # Estadística descriptiva de SO2 so2 &lt;- df %&gt;% filter(Variable == &quot;SO2&quot;) estadistica_so2 &lt;- data.frame(Estadistico = c(&quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot;), Valor = c(min(so2$Promedio, na.rm = TRUE), quantile(so2$Promedio, 0.25, na.rm = TRUE), median(so2$Promedio, na.rm = TRUE), mean(so2$Promedio, na.rm = TRUE), quantile(so2$Promedio, 0.75, na.rm = TRUE), max(so2$Promedio, na.rm = TRUE))) estadistica_so2 %&gt;% mutate(Valor = round(Valor, 2)) %&gt;% knitr::kable(col.names = c(&quot;Estadístico&quot;, &quot;Valor&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:2, border_right = TRUE) Estadístico Valor Mínimo 0.10 Primer cuartil 3.40 Mediana 6.00 Media 9.43 Tercer cuartil 11.00 Máximo 91.71 Interpretación. El SO₂ es muy asimétrico: la media (9,4 µg/m³) es mucho mayor que la mediana (6,0 µg/m³) y el máximo llega a 91,7 µg/m³. Unas pocas estaciones cercanas a fuentes industriales concentran los valores altos. # SO2: promedio y número de registros por año so2_anual &lt;- so2 %&gt;% group_by(Año) %&gt;% summarise(Promedio_SO2 = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) so2_anual %&gt;% mutate(Promedio_SO2 = round(Promedio_SO2, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio SO2&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio SO2 Número de registros 2011 15.14 43 2012 11.26 39 2013 6.84 39 2014 5.92 33 2015 7.26 36 2016 15.92 52 2017 10.35 96 2018 8.34 60 2019 9.80 70 2020 8.71 113 2021 7.81 122 2022 7.14 116 2023 10.08 122 2024 9.86 125 # Evolución del promedio anual de SO2 ggplot(so2_anual, aes(x = Año, y = Promedio_SO2)) + geom_line(linewidth = 1) + geom_point(size = 2.5) + geom_text(aes(label = round(Promedio_SO2, 1)), vjust = -0.8, size = 3.5) + scale_x_continuous(breaks = 2011:2024) + labs(title = &quot;Evolución del promedio anual de SO2&quot;, subtitle = &quot;Periodo 2011–2024&quot;, x = &quot;Año&quot;, y = &quot;Promedio de SO2&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), axis.text.x = element_text(angle = 45, hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(so2_anual$Promedio_SO2) * 1.08) Interpretación. La serie del SO₂ es muy irregular: baja a 5,9 µg/m³ en 2014 y sube a 15,9 µg/m³ en 2016. Ese comportamiento de sierra sugiere que el promedio depende de pocas estaciones industriales que entran y salen de la red. # Porcentaje de cambio de SO2 entre 2011 y 2024 cambio_so2 &lt;- ((so2_anual$Promedio_SO2[so2_anual$Año == 2024] - so2_anual$Promedio_SO2[so2_anual$Año == 2011]) / so2_anual$Promedio_SO2[so2_anual$Año == 2011]) * 100 # Tabla de cambio porcentual de SO2 tabla_cambio_so2 &lt;- data.frame(Periodo = &quot;2011–2024&quot;, SO2_2011 = so2_anual$Promedio_SO2[so2_anual$Año == 2011], SO2_2024 = so2_anual$Promedio_SO2[so2_anual$Año == 2024], Cambio_porcentual = cambio_so2) tabla_cambio_so2 %&gt;% mutate(across(where(is.numeric), ~round(.x, 2))) %&gt;% knitr::kable(col.names = c(&quot;Periodo&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:4, border_right = TRUE) Periodo Promedio 2011 Promedio 2024 Cambio (%) 2011–2024 15.14 9.86 -34.84 Interpretación. La caída de 34,84 % es la mayor de los cinco contaminantes, pero por la irregularidad de la serie no debe leerse como una mejora clara y sostenida. 2.7.6 Comparación del cambio porcentual de los contaminantes comparacion_contaminantes &lt;- data.frame(Contaminante = c(&quot;PM10&quot;, &quot;PM2.5&quot;, &quot;NO2&quot;, &quot;O3&quot;, &quot;SO2&quot;), Promedio_2011 = c(pm10_anual$Promedio_PM10[pm10_anual$Año == 2011], pm25_anual$Promedio_PM25[pm25_anual$Año == 2011], no2_anual$Promedio_NO2[no2_anual$Año == 2011], o3_anual$Promedio_O3[o3_anual$Año == 2011], so2_anual$Promedio_SO2[so2_anual$Año == 2011]), Promedio_2024 = c(pm10_anual$Promedio_PM10[pm10_anual$Año == 2024], pm25_anual$Promedio_PM25[pm25_anual$Año == 2024], no2_anual$Promedio_NO2[no2_anual$Año == 2024], o3_anual$Promedio_O3[o3_anual$Año == 2024], so2_anual$Promedio_SO2[so2_anual$Año == 2024])) comparacion_contaminantes &lt;- comparacion_contaminantes %&gt;% mutate(Cambio_porcentual = ((Promedio_2024 - Promedio_2011) / Promedio_2011) * 100) comparacion_contaminantes %&gt;% mutate(across(where(is.numeric), ~round(.x, 2))) %&gt;% knitr::kable(col.names = c(&quot;Contaminante&quot;, &quot;Promedio 2011&quot;, &quot;Promedio 2024&quot;, &quot;Cambio (%)&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:4, border_right = TRUE) Contaminante Promedio 2011 Promedio 2024 Cambio (%) PM10 42.66 30.83 -27.75 PM2.5 21.46 14.73 -31.35 NO2 36.28 26.88 -25.90 O3 23.94 27.29 14.00 SO2 15.14 9.86 -34.84 # Comparación del cambio porcentual de los principales contaminantes ggplot(comparacion_contaminantes, aes(x = reorder(Contaminante, Cambio_porcentual), y = Cambio_porcentual)) + geom_col() + geom_text(aes(label = paste0(round(Cambio_porcentual, 1), &quot;%&quot;)), hjust = ifelse(comparacion_contaminantes$Cambio_porcentual &lt; 0, 1.1, -0.1), size = 3.5) + coord_flip() + labs(title = &quot;Cambio porcentual de los principales contaminantes&quot;, subtitle = &quot;Variación del promedio entre 2011 y 2024&quot;, x = &quot;Contaminante&quot;, y = &quot;Cambio porcentual (%)&quot;) + theme_minimal() + theme(plot.title = element_text(face = &quot;bold&quot;, size = 16), plot.subtitle = element_text(size = 11), panel.grid.major.y = element_blank(), panel.grid.minor = element_blank()) + expand_limits(y = range(comparacion_contaminantes$Cambio_porcentual) * 1.15) Interpretación. Cuatro de los cinco contaminantes bajaron entre 2011 y 2024, y el material particulado, el más relevante para la salud, se redujo cerca de 30 %. El ozono es la excepción. El tamaño del cambio no indica qué tan confiable es: el SO₂ tiene la mayor caída pero la serie más irregular, y el PM10 una caída menor pero la tendencia más estable. 2.8 Análisis de variables meteorológicas Objetivo específico 1 · variables meteorológicas. 2.8.1 Temperatura del aire (TAire) # Estadística descriptiva de TAire taire &lt;- df %&gt;% filter(Variable == &quot;TAire&quot;) estadistica_taire &lt;- data.frame(Estadistico = c(&quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot;), Va