 hjust = 1), panel.grid.minor = element_blank()) + expand_limits(y = max(taire_anual$Promedio_TAire) * 1.08) Interpretación. La subida de 20,9 °C a 24,9 °C no es un cambio climático plausible en 8 años: refleja que cambiaron las estaciones que reportan (una estación en tierra caliente sube el promedio). TAire2 y TAire10 tienen muchos más registros y son mejores variables para estudiar la temperatura. 2.8.2 Humedad relativa del aire (HAire) # Estadística descriptiva de HAire haire &lt;- df %&gt;% filter(Variable == &quot;HAire&quot;) estadistica_haire &lt;- data.frame(Estadistico = c(&quot;Mínimo&quot;, &quot;Primer cuartil&quot;, &quot;Mediana&quot;, &quot;Media&quot;, &quot;Tercer cuartil&quot;, &quot;Máximo&quot;), Valor = c(min(haire$Promedio, na.rm = TRUE), quantile(haire$Promedio, 0.25, na.rm = TRUE), median(haire$Promedio, na.rm = TRUE), mean(haire$Promedio, na.rm = TRUE), quantile(haire$Promedio, 0.75, na.rm = TRUE), max(haire$Promedio, na.rm = TRUE))) estadistica_haire %&gt;% mutate(Valor = round(Valor, 2)) %&gt;% knitr::kable(col.names = c(&quot;Estadístico&quot;, &quot;Valor&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:2, border_right = TRUE) Estadístico Valor Mínimo 33.10 Primer cuartil 62.05 Mediana 71.80 Media 66.09 Tercer cuartil 76.35 Máximo 92.00 # HAire: promedio y número de registros por año haire_anual &lt;- haire %&gt;% group_by(Año) %&gt;% summarise(Promedio_HAire = mean(Promedio, na.rm = TRUE), Registros = n(), .groups = &quot;drop&quot;) haire_anual %&gt;% mutate(Promedio_HAire = round(Promedio_HAire, 2)) %&gt;% knitr::kable(col.names = c(&quot;Año&quot;, &quot;Promedio HAire&quot;, &quot;Número de registros&quot;)) %&gt;% kableExtra::kable_styling(full_width = FALSE, position = &quot;left&quot;) %&gt;% kableExtra::column_spec(1:3, border_right = TRUE) Año Promedio HAire Número de registros 2011 71.90 4 2012 70.70 2 2013 72.55 2 2014 68.34 5 2017 65.51 36 2018 62.38 